export default class Tag {

  constructor(el) {
    this.closeTimeout = false;

    // selectors
    this.domSelectors = {
      tag: '.b_tag',
    };

    // classes
    this.classes = {
      active: 'active',
    };

    this.content = el.textContent;
    console.log(el.textContent, "Text content");

    this.element = document.querySelector(this.domSelectors.tag);

    // init
    this.init();
  }


  init() {
    console.log("Init for tag called!");
    console.log(this.content);
  }
}
